  var line = panelA.line(p.x, p.y, q.x, q.y).stroke({ color: COL.edge, width: 3.3, linecap: 'round' });
  graphEdgeLines.push(line);
  var hit = hitLayer.line(p.x, p.y, q.x, q.y).stroke({ color: '#000', width: 18, opacity: 0, linecap: 'round' });
  (function (idx, aa, bb) {
    hit.css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Edge (' + aa + ', ' + bb + '): one graph line, two symmetric A entries, one E column.', ev); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { selectEdge(idx); });
  })(e, a, b);
}

for (var ns = 1; ns <= 6; ns++) {
  var nsp = nodeStackPos[ns];
  var col = [];
  for (var rr = 0; rr < 5; rr++) col.push(nodeData[rr][ns - 1]);
  stackCells(panelA, nsp.x, nsp.y, col, 16, 3, 'Node ' + ns + ' feature vector: column ' + ns + ' of X.', (function (id) {
    return function () { selectNode(id); };
  })(ns));
}

for (var es = 0; es < edgeStackPos.length; es++) {
  var esp = edgeStackPos[es];
  var ecol = [];
  for (var erow = 0; erow < 4; erow++) ecol.push(edgeData[erow][es]);
  stackCells(panelA, esp.x, esp.y, ecol, 16, 3, 'Edge (' + edges[es][0] + ', ' + edges[es][1] + ') feature vector: column ' + (es + 1) + ' of E.', (function (idx) {
    return function () { selectEdge(idx); };
  })(es));
}

var nodeGroups = {};
for (var id = 1; id <= 6; id++) {
  var ng = panelA.group();
  ng.circle(62).center(nodes[id].x, nodes[id].y).fill('#fff').stroke({ color: COL.nodeStroke, width: 3.2 });
  ng.text(String(id)).font({ family: 'Arial, sans-serif', size: 32 }).fill('#000').center(nodes[id].x, nodes[id].y + 1);
  (function (nid) {
    ng.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Node ' + nid + ': row/column ' + nid + ' in A and column ' + nid + ' in X.', e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { selectNode(nid); });
  })(id);
  nodeGroups[id] = ng;
}

multiText(panelB, ['Adjacency', 'matrix, A', 'N × N'], 952, 83, 34, COL.edge, 'Georgia, serif', 'middle', 7);

var A0 = { x: 851, y: 243, c: 32, gap: 6 };
var adjCells = {};
var adjSet = {};
edges.forEach(function (ed) {
  adjSet[ed[0] + ',' + ed[1]] = true;
  adjSet[ed[1] + ',' + ed[0]] = true;
});
for (var c = 1; c <= 6; c++) {
  addText(panelB, String(c), A0.x + (c - 1) * (A0.c + A0.gap) + A0.c / 2, 226, 30, '#000', 'Arial, sans-serif', 'middle');
}
for (var r = 1; r <= 6; r++) {
  addText(panelB, String(r), A0.x - 18, A0.y + (r - 1) * (A0.c + A0.gap) + A0.c / 2, 30, '#000', 'Arial, sans-serif', 'middle');
  for (var cc = 1; cc <= 6; cc++) {
    var filled = !!adjSet[r + ',' + cc];
    var rect = panelB.rect(A0.c, A0.c)
      .move(A0.x + (cc - 1) * (A0.c + A0.gap), A0.y + (r - 1) * (A0.c + A0.gap))
      .fill(filled ? COL.adj : '#fff')
      .stroke({ color: COL.grid, width: 3.5 });
    adjCells[r + ',' + cc] = rect;
    if (filled) {
      (function (rrr, ccc) {
        rect.css('cursor', 'pointer')
          .on('mousemove', function (ev) { showTooltip('A' + rrr + ccc + ' = 1 because nodes ' + rrr + ' and ' + ccc + ' are connected.', ev); })
          .on('mouseleave', function () { hideTooltip(); })
          .on('click', function () { selectEdge(edgeIndexByPair[rrr + '-' + ccc]); });
      })(r, cc);
    }
  }
}

multiText(panelC, ['Node', 'data, X', 'D × N'], 1302, 73, 32, COL.nodeStroke, 'Georgia, serif', 'middle', 6);

var X0 = { x: 1403, y: 53, c: 32, gap: 6 };
var xCells = {};
for (var xc = 1; xc <= 6; xc++) {
  addText(panelC, String(xc), X0.x + (xc - 1) * (X0.c + X0.gap) + X0.c / 2, 36, 32, '#000', 'Arial, sans-serif', 'middle');
}
for (var xr = 0; xr < 5; xr++) {
  for (var xcc = 0; xcc < 6; xcc++) {
    var xrect = panelC.rect(X0.c, X0.c)
      .move(X0.x + xcc * (X0.c + X0.gap), X0.y + xr * (X0.c + X0.gap))
      .fill(nodeData[xr][xcc])
      .stroke({ color: COL.grid, width: 3.5 });
    xCells[(xr + 1) + ',' + (xcc + 1)] = xrect;
    (function (nodeId) {
      xrect.css('cursor', 'pointer')
        .on('mousemove', function (ev) { showTooltip('Column ' + nodeId + ' of X stores the feature vector for node ' + nodeId + '.', ev); })
        .on('mouseleave', function () { hideTooltip(); })
        .on('click', function () { selectNode(nodeId); });
    })(xcc + 1);
  }
}

multiText(panelD, ['Edge', 'data, E', 'Dₑ × E'], 1305, 389, 32, '#2d8e84', 'Georgia, serif', 'middle', 6);

var E0 = { x: 1380, y: 391, c: 32, gap: 6 };
var eCells = {};
for (var ec = 0; ec < 7; ec++) {
  addText(panelD, String(edges[ec][0]), E0.x + ec * (E0.c + E0.gap) + E0.c / 2, 318, 30, '#000', 'Arial, sans-serif', 'middle');
  addText(panelD, String(edges[ec][1]), E0.x + ec * (E0.c + E0.gap) + E0.c / 2, 362, 30, '#000', 'Arial, sans-serif', 'middle');
}
for (var eR = 0; eR < 4; eR++) {
  for (var eC = 0; eC < 7; eC++) {
    var erect = panelD.rect(E0.c, E0.c)
      .move(E0.x + eC * (E0.c + E0.gap), E0.y + eR * (E0.c + E0.gap))
      .fill(edgeData[eR][eC])
      .stroke({ color: COL.grid, width: 3.5 });
    eCells[(eR + 1) + ',' + (eC + 1)] = erect;
    (function (idx) {
      erect.css('cursor', 'pointer')
        .on('mousemove', function (ev) { showTooltip('Column ' + (idx + 1) + ' of E stores features for edge (' + edges[idx][0] + ', ' + edges[idx][1] + ').', ev); })
        .on('mouseleave', function () { hideTooltip(); })
        .on('click', function () { selectEdge(idx); });
    })(eC);
  }
}

function rowY(r) { return A0.y + (r - 1) * (A0.c + A0.gap); }
function colX(c) { return A0.x + (c - 1) * (A0.c + A0.gap); }
function matrixWidth(n, cell, gap) { return n * cell + (n - 1) * gap; }

function redrawHighlight() {
  highlight.clear();

  if (selectedNode != null) {
    var n = selectedNode;
    var gridW = matrixWidth(6, A0.c, A0.gap);
    highlight.rect(gridW, A0.c).move(A0.x, rowY(n)).fill({ color: COL.hi, opacity: 0.22 }).stroke('none');
    highlight.rect(A0.c, gridW).move(colX(n), A0.y).fill({ color: COL.hi, opacity: 0.22 }).stroke('none');
    highlight.rect(gridW, A0.c).move(A0.x, rowY(n)).fill('none').stroke({ color: COL.hi, width: 4 });
    highlight.rect(A0.c, gridW).move(colX(n), A0.y).fill('none').stroke({ color: COL.hi, width: 4 });

    var xCol = X0.x + (n - 1) * (X0.c + X0.gap);
    highlight.rect(X0.c, matrixWidth(5, X0.c, X0.gap)).move(xCol, X0.y)
      .fill({ color: COL.hi, opacity: 0.18 }).stroke({ color: COL.hi, width: 5 });

    highlight.circle(76).center(nodes[n].x, nodes[n].y).fill('none').stroke({ color: COL.hi2, width: 6 });

    addText(highlight, 'node ' + n, nodes[n].x, nodes[n].y - 58, 18, COL.nodeStroke, 'Arial, sans-serif', 'middle')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }

  if (selectedEdge != null) {
    var ed = edges[selectedEdge], u = ed[0], v = ed[1];
    var p = nodes[u], q = nodes[v];

    highlight.line(p.x, p.y, q.x, q.y).stroke({ color: COL.hi2, width: 9, linecap: 'round', opacity: 0.82 });
    highlight.circle(73).center(p.x, p.y).fill('none').stroke({ color: COL.hi2, width: 5 });
    highlight.circle(73).center(q.x, q.y).fill('none').stroke({ color: COL.hi2, width: 5 });

    highlight.rect(A0.c, A0.c).move(colX(v), rowY(u)).fill({ color: COL.hi, opacity: 0.28 }).stroke({ color: COL.hi2, width: 5 });
    highlight.rect(A0.c, A0.c).move(colX(u), rowY(v)).fill({ color: COL.hi, opacity: 0.28 }).stroke({ color: COL.hi2, width: 5 });

    var eCol = E0.x + selectedEdge * (E0.c + E0.gap);
    highlight.rect(E0.c, matrixWidth(4, E0.c, E0.gap)).move(eCol, E0.y)
      .fill({ color: COL.hi, opacity: 0.18 }).stroke({ color: COL.hi2, width: 5 });

    addText(highlight, '(' + u + ', ' + v + ')', (p.x + q.x) / 2, (p.y + q.y) / 2 - 20, 18, COL.nodeStroke, 'Arial, sans-serif', 'middle')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }

  highlight.front();
}

function selectNode(n) {
  selectedNode = n;
  selectedEdge = null;
  redrawHighlight();
  showPopup('Node ' + n, 'This graph node is row ' + n + ' and column ' + n + ' in the adjacency matrix A. Its attributes are stored together as column ' + n + ' of the node feature matrix X.');
}

function selectEdge(idx) {
  if (idx == null || idx < 0) return;
  selectedEdge = idx;
  selectedNode = null;
  redrawHighlight();
  var ed = edges[idx];
  showPopup('Edge (' + ed[0] + ', ' + ed[1] + ')', 'This undirected edge appears twice in A: cells A' + ed[0] + ed[1] + ' and A' + ed[1] + ed[0] + '. Its edge attributes are stored once as column ' + (idx + 1) + ' of E.');
}

function update_representationView(v) {
  activeView = v;
  var keys = Object.keys(panels);
  for (var i = 0; i < keys.length; i++) {
    var g = panels[keys[i]];
    if (v === 'All panels' || v === keys[i]) {
      g.opacity(1);
    } else {
      g.opacity(0.13);
    }
  }
  hitLayer.opacity(v === 'All panels' || v === 'a) Graph' ? 1 : 0.1);
  if (document.getElementById('representationViewInput')) {
    document.getElementById('representationViewInput').value = v;
  }
  redrawHighlight();
}

var demoSteps = [
  {
    title: 'Start with the graph',
    narration: 'Panel a shows the graph as circles and connecting lines. The stacked cells near nodes and edges indicate feature vectors.',
    state: { representationView: 'a) Graph' }
  },
  {
    title: 'Connectivity becomes A',
    narration: 'Every filled cell in A marks a connected pair. Because the graph is undirected, the filled cells are symmetric.',
    state: { representationView: 'b) Adjacency A' }
  },
  {
    title: 'Nodes become columns of X',
    narration: 'Each node label names a column of X, and that column stores the node’s feature vector.',
    state: { representationView: 'c) Node data X' }
  },
  {
    title: 'Edges become columns of E',
    narration: 'Each E column is indexed by an endpoint pair such as 1–3 or 4–5, storing edge attributes separately.',
    state: { representationView: 'd) Edge data E' }
  },
  {
    title: 'Link the representations',
    narration: 'Return to all panels and click a node or edge. Highlights show how one graph object maps into A, X, and E.',
    state: { representationView: 'All panels' }
  }
];

var currentStep = 0;

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length;
  if (st.state && st.state.representationView) {
    update_representationView(st.state.representationView);
  }
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A graph for a graph neural network is represented by three linked data structures: an adjacency matrix for connectivity, a node feature matrix for node attributes, and an edge feature matrix for edge attributes.
KEY INSIGHT (what students should walk away understanding): The graph picture and the matrices are not separate objects: nodes, edges, connectivity, and attributes are the same information organized into different arrays.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A graph for a graph neural network is represented by three linked data structures: an adjacency matrix for connectivity, a node feature matrix for node attributes, and an edge feature matrix for edge attributes.",
  "figureType": "diagram",
  "elements": [
    "panel label 'a)' for the graph diagram",
    "six white circular graph nodes with brown outlines labeled 1, 2, 3, 4, 5, 6",
    "undirected graph edge between nodes 1 and 3",
    "undirected graph edge between nodes 1 and 4",
    "undirected graph edge between nodes 2 and 3",
    "undirected graph edge between nodes 3 and 4",
    "undirected graph edge between nodes 3 and 6",
    "undirected graph edge between nodes 4 and 5",
    "undirected graph edge between nodes 5 and 6",
    "edge identity labels or implied endpoint-pair labels for edges (1,3), (1,4), (2,3), (3,4), (3,6), (4,5), (5,6)",
    "six vertical node-feature stacks near the graph nodes, each drawn as a column of small square cells in brown and peach tones",
    "seven vertical edge-feature stacks near graph edges, each drawn as a column of small square cells in teal tones",
    "panel label 'b)' for the adjacency matrix",
    "title text 'Adjacency matrix, A, N × N'",
    "6 by 6 adjacency matrix grid with column labels 1 through 6 and row labels 1 through 6",
    "blue-gray filled adjacency cells at positions A13, A14, A23, A31, A32, A34, A36, A41, A43, A45, A54, A56, A63, A65",
    "white adjacency cells for non-edges and diagonal entries",
    "panel label 'c)' for the node data matrix",
    "label text 'Node data, X, D × N'",
    "node data matrix X with 5 feature rows and 6 node columns",
    "column labels 1 through 6 above node data matrix X",
    "colored node-feature cells in brown, peach, and dark-brown tones",
    "panel label 'd)' for the edge data matrix",
    "label text 'Edge data, E, D_E × E'",
    "two-line edge endpoint header above edge data matrix E showing ordered edge columns: first row 1, 1, 2, 3, 3, 4, 5 and second row 3, 4, 3, 4, 6, 5, 6",
    "edge data matrix E with 4 feature rows and 7 edge columns",
    "colored edge-feature cells in teal, pale teal, and dark teal tones",
    "highlight style for selected graph node, selected graph edge, selected adjacency row and column, selected node-feature column, and selected edge-feature column"
  ],
  "interactions": [
    {
      "id": "representationView",
      "type": "toggle",
      "label": "Representation view",
      "options": [
        "All panels",
        "a) Graph",
        "b) Adjacency A",
        "c) Node data X",
        "d) Edge data E"
      ],
      "default": "All panels",
      "teaches": "The same graph can be viewed as a visual network, a connectivity matrix, a node-attribute table, or an edge-attribute table"
    },
    {
      "id": "selectNode",
      "type": "click",
      "teaches": "A node corresponds to one row and one column in the adjacency matrix and to one column in the node feature matrix"
    },
    {
      "id": "selectEdge",
      "type": "click",
      "teaches": "An edge corresponds to a pair of connected nodes in the graph, two symmetric adjacency entries, and one column in the edge feature matrix"
    }
  ],
  "demo_steps": [
    {
      "title": "Start with the graph",
      "narration": "Panel a shows the graph as circles and connecting lines. The small stacked cells near nodes and edges indicate that both nodes and edges can carry feature vectors.",
      "state": {
        "representationView": "a) Graph"
      }
    },
    {
      "title": "Connectivity becomes A",
      "narration": "Switch to the adjacency matrix: every filled cell marks a pair of nodes connected by an edge. Because the graph is undirected, the matrix is symmetric.",
      "state": {
        "representationView": "b) Adjacency A"
      }
    },
    {
      "title": "Nodes become columns of X",
      "narration": "Switch to node data: each node label now names a column of X, and each column stores that node's feature vector.",
      "state": {
        "representationView": "c) Node data X"
      }
    },
    {
      "title": "Edges become columns of E",
      "narration": "Switch to edge data: each column of E is indexed by an endpoint pair such as 1–3 or 4–5, so edge attributes are stored separately from node attributes.",
      "state": {
        "representationView": "d) Edge data E"
      }
    },
    {
      "title": "Link the representations",
      "narration": "Return to all panels and click a node or edge. The highlights show how a single graph object maps to the corresponding matrix rows, columns, and feature vectors.",
      "state": {
        "representationView": "All panels"
      }
    }
  ],
  "keyInsight": "The graph picture and the matrices are not separate objects: nodes, edges, connectivity, and attributes are the same information organized into different arrays.",
  "reconstructionNotes": "Use a wide four-panel layout matching the source: graph on the left, adjacency matrix in the middle, node data in the upper right, and edge data in the lower right. Draw graph edges in blue-gray and nodes as white circles with brown outlines and black labels. Place node 3 near the lower-left center as a hub connected to nodes 1, 2, 4, and 6; node 4 connects onward to 5, and 5 connects to 6. Use brown/peach color palettes for node features and teal palettes for edge features. The adjacency matrix should be a 6×6 square grid with dark outlines and blue-gray filled cells for the seven undirected edges in both symmetric positions. When a node is clicked, highlight that node in panel a, its full row and column in A, and its column in X. When an edge is clicked, thicken or glow the graph edge and its two endpoint nodes, highlight the two symmetric cells in A, and highlight the matching column in E according to the edge order (1,3), (1,4), (2,3), (3,4), (3,6), (4,5), (5,6)."
}

