function rowY(r) { return A0.y + (r - 1) * (A0.c + A0.gap); }
function colX(c) { return A0.x + (c - 1) * (A0.c + A0.gap); }
function matrixWidth(n, cell, gap) { return n * cell + (n - 1) * gap; }

function redrawHighlight() {
  highlight.clear();

  if (selectedNode != null) {
    var n = selectedNode;
    var gridW = matrixWidth(6, A0.c, A0.gap);
    highlight.rect(gridW, A0.c).move(A0.x, rowY(n)).fill({ color: COL.hi, opacity: 0.22 }).stroke('none');
    highlight.rect(A0.c, gridW).move(colX(n), A0.y).fill({ color: COL.hi, opacity: 0.22 }).stroke('none');
    highlight.rect(gridW, A0.c).move(A0.x, rowY(n)).fill('none').stroke({ color: COL.hi, width: 4.5 });
    highlight.rect(A0.c, gridW).move(colX(n), A0.y).fill('none').stroke({ color: COL.hi, width: 4.5 });

    var xCol = X0.x + (n - 1) * (X0.c + X0.gap);
    highlight.rect(X0.c, matrixWidth(5, X0.c, X0.gap)).move(xCol, X0.y)
      .fill({ color: COL.hi, opacity: 0.18 }).stroke({ color: COL.hi, width: 5 });

    highlight.circle(80).center(nodes[n].x, nodes[n].y).fill('none').stroke({ color: COL.hi2, width: 6 });

    addText(highlight, 'node ' + n, nodes[n].x, nodes[n].y - 61, 20, COL.nodeStroke, 'Arial, sans-serif', 'middle')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  }

  if (selectedEdge != null) {
    var ed = edges[selectedEdge], u = ed[0], v = ed[1];
