    highlight.line(p.x, p.y, q.x, q.y).stroke({ color: COL.hi2, width: 10, linecap: 'round', opacity: 0.82 });
    highlight.circle(78).center(p.x, p.y).fill('none').stroke({ color: COL.hi2, width: 5.5 });
    highlight.circle(78).center(q.x, q.y).fill('none').stroke({ color: COL.hi2, width: 5.5 });

    highlight.rect(A0.c, A0.c).move(colX(v), rowY(u)).fill({ color: COL.hi, opacity: 0.28 }).stroke({ color: COL.hi2, width: 5 });
    highlight.rect(A0.c, A0.c).move(colX(u), rowY(v)).fill({ color: COL.hi, opacity: 0.28 }).stroke({ color: COL.hi2, width: 5 });

    var eCol = E0.x + selectedEdge * (E0.c + E0.gap);
