function selectNode(n) {
  selectedNode = n;
  selectedEdge = null;
  redrawHighlight();
  showPopup('Node ' + n, 'This graph node is row ' + n + ' and column ' + n + ' in the adjacency matrix A. Its attributes are stored together as column ' + n + ' of the node feature matrix X.');
}

function selectEdge(idx) {
  if (idx == null || idx < 0) return;
  selectedEdge = idx;
  selectedNode = null;
  redrawHighlight();
  var ed = edges[idx];
  showPopup('Edge (' + ed[0] + ', ' + ed[1] + ')', 'This undirected edge appears twice in A: cells A' + ed[0] + ed[1] + ' and A' + ed[1] + ed[0] + '. Its edge attributes are stored once as column ' + (idx + 1) + ' of E.');
}

function update_representationView(v, userInitiated) {
  activeView = v;
  focusFrame.clear();

  var keys = Object.keys(panels);
  for (var i = 0; i < keys.length; i++) {
    var g = panels[keys[i]];
    if (v === 'All panels' || v === keys[i]) {
      g.opacity(1);
    } else {
      g.opacity(0.78);
    }
  }
  hitLayer.opacity(v === 'All panels' || v === 'a) Graph' ? 1 : 0.35);

  if (v !== 'All panels') {
    var b = panelBounds[v];
    focusFrame.rect(b.w - 12, b.h - 16).move(b.x + 6, b.y + 8)
      .fill('none')
      .stroke({ color: COL.focusBorder, width: 2.4, dasharray: '9,8', opacity: 0.34 });
  }

  var sel = document.getElementById('representationViewInput');
  if (sel) sel.value = v;
  redrawHighlight();
}

